mod solution;

fn main() {
    let cases = [
    (r#"n=5 updates=(1,3,3),(2,4,2)"#, r#"0,3,5,5,2"#),
    (r#"n=4 updates=(0,1,2),(2,3,1)"#, r#"2,2,1,1"#),
    (r#"
n=4 updates=(0,1,2),(2,3,1)
"#, r#"2,2,1,1"#),
    (r#"  
n=5 updates=(1,3,3),(2,4,2)
  "#, r#"0,3,5,5,2"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS difference-array");
}
